"""
Typing names for mref, for use in annotations:

    shape: mref.types.MeshNode = mref.get("pCube1Shape")

The real definitions live in ``types.pyi``, which IDEs and type checkers
read instead of this file. It is generated by ``mref.generate_stubs()``
— re-run that after adding or changing traits.

At runtime every ``<NodeType>Node``, ``<Name>Trait`` and ``Attribute``
name resolves to ``ReferencedItem``, so annotations which are evaluated
(function signatures, module-level variables) still work.
"""
from .core import ReferencedItem


def __getattr__(name: str):
    if name == "Attribute" or name.endswith("Node") or name.endswith("Trait"):
        return ReferencedItem
    raise AttributeError(f"module 'mref.types' has no attribute {name!r}")
